CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS uploads (filename TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, mime_type TEXT, content BYTEA, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE uploads ADD COLUMN IF NOT EXISTS mime_type TEXT;
ALTER TABLE uploads ADD COLUMN IF NOT EXISTS content BYTEA;
CREATE TABLE IF NOT EXISTS items (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL, subcategory TEXT, color TEXT, style TEXT, season TEXT, formality TEXT, brand TEXT, size TEXT, price NUMERIC(12,2), bought_at DATE, notes TEXT, image TEXT NOT NULL, favorite SMALLINT NOT NULL DEFAULT 0, destination TEXT, condition TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS looks (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, occasion TEXT, style TEXT, origin TEXT NOT NULL DEFAULT 'manual', favorite SMALLINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS look_items (look_id UUID NOT NULL REFERENCES looks(id) ON DELETE CASCADE, item_id UUID NOT NULL REFERENCES items(id) ON DELETE RESTRICT, PRIMARY KEY(look_id,item_id));
CREATE TABLE IF NOT EXISTS uses (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, look_id UUID NOT NULL REFERENCES looks(id) ON DELETE CASCADE, used_at DATE NOT NULL, liked SMALLINT, again SMALLINT, notes TEXT);
CREATE TABLE IF NOT EXISTS plans (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, look_id UUID NOT NULL REFERENCES looks(id) ON DELETE CASCADE, planned_at DATE NOT NULL, confirmed SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, styles TEXT, colors TEXT, avoid_colors TEXT, item_types TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS capsules (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS capsule_items (capsule_id UUID NOT NULL REFERENCES capsules(id) ON DELETE CASCADE, item_id UUID NOT NULL REFERENCES items(id) ON DELETE CASCADE, PRIMARY KEY(capsule_id,item_id));
CREATE TABLE IF NOT EXISTS inspirations (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, image TEXT NOT NULL, title TEXT NOT NULL, category TEXT, color TEXT, style TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, look_id UUID NOT NULL UNIQUE REFERENCES looks(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS saved_posts (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id UUID NOT NULL REFERENCES posts(id) ON DELETE CASCADE, PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS trips (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, destination TEXT NOT NULL, starts_at DATE NOT NULL, ends_at DATE NOT NULL, activities TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trip_looks (trip_id UUID NOT NULL REFERENCES trips(id) ON DELETE CASCADE, look_id UUID NOT NULL REFERENCES looks(id) ON DELETE CASCADE, day DATE NOT NULL, activity TEXT, PRIMARY KEY(trip_id,look_id,day));
CREATE TABLE IF NOT EXISTS trip_packed (trip_id UUID NOT NULL REFERENCES trips(id) ON DELETE CASCADE, item_id UUID NOT NULL REFERENCES items(id) ON DELETE CASCADE, PRIMARY KEY(trip_id,item_id));
CREATE TABLE IF NOT EXISTS feedback (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_ids JSONB NOT NULL, occasion TEXT, liked SMALLINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_items_user ON items(user_id);
CREATE INDEX IF NOT EXISTS idx_looks_user ON looks(user_id);
CREATE INDEX IF NOT EXISTS idx_uses_user ON uses(user_id);
CREATE INDEX IF NOT EXISTS idx_trips_user ON trips(user_id);

